using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class ApprovalReminderTests
{
 class Time:TimeProvider{public DateTimeOffset Now=new(2026,11,24,18,0,0,TimeSpan.Zero);public override DateTimeOffset GetUtcNow()=>Now;}
 class User:ICurrentUser{public string Email=>"admin@example.local";public int? EmployeeId=>1;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>true;public bool Can(string p)=>true;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));foreach(var a in await d.Set<AdvanceRequest>().ToListAsync())a.Status=RequestStatus.Cancelled;d.Add(new AppUser{Email="reminder7@example.local",EmployeeId=7,IsActive=true,RoleList=Roles.Employee,PasswordHash="unused"});await d.SaveAsync();return d;}
 static WorkflowService W(AppDbContext d,Time t){var u=new User();return new(d,u,new AuditService(d,u,new AppClock(t)));}
 static async Task<AdvanceRequest> Request(AppDbContext d,Time t){var a=new AdvanceRequest{EmployeeId=6,Amount=1000,Installments=2,Route=Roles.FinanceManager,CreatedAt=t.Now.UtcDateTime.AddHours(-24)};d.Add(a);await d.SaveAsync();return a;}
 [Fact]public async Task DisabledByDefaultAndDueOnlyAfterExplicitElapsedHours(){await using var d=await Db();var t=new Time();var a=await Request(d,t);var s=new ApprovalReminders(d,new AppClock(t));await s.RunAsync();Assert.Empty(await d.Set<ApprovalReminder>().ToListAsync());await W(d,t).SetReminderHoursAsync("Advance",25);await s.RunAsync();Assert.Empty(await d.Set<ApprovalReminder>().ToListAsync());t.Now=t.Now.AddHours(1);await s.RunAsync();Assert.NotEmpty(await d.Set<ApprovalReminder>().ToListAsync());Assert.Equal(RequestStatus.Pending,a.Status);Assert.Equal(0,a.StageIndex);}
 [Fact]public async Task DailyDedupAndNewStageResetsClock(){await using var d=await Db();var t=new Time();var a=await Request(d,t);await W(d,t).SetReminderHoursAsync("Advance",1);var s=new ApprovalReminders(d,new AppClock(t));int mail=await d.Set<EmailOutbox>().CountAsync();await s.RunAsync();int count=await d.Set<ApprovalReminder>().CountAsync();await s.RunAsync();Assert.Equal(count,await d.Set<ApprovalReminder>().CountAsync());Assert.Equal(mail,await d.Set<EmailOutbox>().CountAsync());t.Now=t.Now.AddDays(1);await s.RunAsync();Assert.Equal(2*count,await d.Set<ApprovalReminder>().CountAsync());a.Route=Roles.FinanceManager+","+Roles.HRManager;a.StageIndex=1;d.Add(new ApprovalAction{Kind="Advance",RequestId=a.Id,Action="Approved:"+Roles.FinanceManager,At=t.Now.UtcDateTime});await d.SaveAsync();await s.RunAsync();Assert.DoesNotContain(await d.Set<ApprovalReminder>().ToListAsync(),x=>x.StageIndex==1);t.Now=t.Now.AddHours(1);await s.RunAsync();Assert.Contains(await d.Set<ApprovalReminder>().ToListAsync(),x=>x.StageIndex==1);}
 [Fact]public async Task ReassignmentAndActiveAccountsLimitRecipientsAndPrivateContentIsOmitted(){await using var d=await Db();var t=new Time();var a=await Request(d,t);var target=await d.Set<AppUser>().FirstAsync(x=>x.EmployeeId==7);d.Add(new ApprovalAssignment{Kind="Advance",RequestId=a.Id,StageIndex=0,ToUserId=target.Id,At=t.Now.UtcDateTime.AddHours(-2)});await d.SaveAsync();await W(d,t).SetReminderHoursAsync("Advance",1);await new ApprovalReminders(d,new AppClock(t)).RunAsync();var users=await d.Set<AppUser>().ToListAsync();var rows=await d.Set<ApprovalReminder>().Where(x=>x.RequestId==a.Id).ToListAsync();Assert.Contains(rows,x=>x.UserId==target.Id);Assert.All(rows,x=>Assert.True(x.UserId==target.Id||users.Single(u=>u.Id==x.UserId).RoleArray.Contains(Roles.SystemAdmin)));Assert.All(await d.Set<Notification>().Where(x=>x.TitleKey=="notif.approvalReminder").ToListAsync(),x=>Assert.DoesNotContain("1000",x.Details));target.IsActive=false;t.Now=t.Now.AddDays(1);await d.SaveAsync();await new ApprovalReminders(d,new AppClock(t)).RunAsync();Assert.DoesNotContain(await d.Set<ApprovalReminder>().ToListAsync(),x=>x.OnDate==new AppClock(t).Today&&x.UserId==target.Id);}
 [Fact]public async Task DecisionsStopRemindersAndMarkersAreImmutable(){await using var d=await Db();var t=new Time();var a=await Request(d,t);await W(d,t).SetReminderHoursAsync("Advance",1);var s=new ApprovalReminders(d,new AppClock(t));await s.RunAsync();int count=await d.Set<ApprovalReminder>().CountAsync();a.Status=RequestStatus.Cancelled;await d.SaveAsync();t.Now=t.Now.AddDays(1);await s.RunAsync();Assert.Equal(count,await d.Set<ApprovalReminder>().CountAsync());(await d.Set<ApprovalReminder>().FirstAsync()).StageIndex=20;await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task DelegatesAreIncludedButSubjectIsExcludedAndInvalidPolicyRejected(){await using var d=await Db();var t=new Time();var a=await Request(d,t);var source=await d.Set<AppUser>().FirstAsync(x=>x.Email=="finance@peoplehub.local");d.Add(new Delegation{FromEmployeeId=source.EmployeeId!.Value,ToEmployeeId=7,StartDate=new AppClock(t).Today,EndDate=new AppClock(t).Today});d.Add(new AppUser{Email="subject@example.local",EmployeeId=6,RoleList=Roles.SystemAdmin,PasswordHash="unused",IsActive=true});await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>W(d,t).SetReminderHoursAsync("Unknown",1));await Assert.ThrowsAsync<DomainException>(()=>W(d,t).SetReminderHoursAsync("Advance",-1));await W(d,t).SetReminderHoursAsync("Advance",1);await new ApprovalReminders(d,new AppClock(t)).RunAsync();var target=await d.Set<AppUser>().FirstAsync(x=>x.EmployeeId==7);var subject=await d.Set<AppUser>().FirstAsync(x=>x.Email=="subject@example.local");var rows=await d.Set<ApprovalReminder>().ToListAsync();Assert.Contains(rows,x=>x.UserId==target.Id);Assert.DoesNotContain(rows,x=>x.UserId==subject.Id);}
}
